/**
 * Builds supabase/setup.sql: every migration in order, then the seed and the
 * scheduled jobs, so a new Supabase project can be set up by pasting ONE file
 * into the SQL Editor.   npm run setup:sql
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = "supabase/migrations";
const parts = [
  "-- DEMO: complete database setup for a NEW Supabase project.",
  "-- Generated by scripts/build-setup-sql.ts. Paste into Supabase → SQL Editor → Run.",
  "-- Run it once. To update an existing project later, run only the new migration files.",
  "",
];
for (const f of readdirSync(dir).filter((f) => f.endsWith(".sql")).sort()) {
  parts.push(`-- ═════ ${f} ═════`, readFileSync(`${dir}/${f}`, "utf8").trim(), "");
}
parts.push("-- ═════ seed (demo catalogue, categories, delivery zones, coupons) ═════", readFileSync("supabase/seed.sql", "utf8").trim(), "");
parts.push(
  "-- ═════ scheduled jobs (needs the pg_cron extension: Database → Extensions → pg_cron) ═════",
  `do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('release-unpaid-orders', '*/10 * * * *', 'select public.release_unpaid_orders()');
    perform cron.schedule('prune-rate-limits', '17 3 * * *', 'select public.prune_rate_limits()');
  else
    raise notice 'pg_cron is not enabled: enable it, then re-run just this block.';
  end if;
end $$;`,
  "",
);
writeFileSync("supabase/setup.sql", parts.join("\n"));
console.log("supabase/setup.sql written");
